contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function as the test entry point
    function run(uint dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);

        // record balances before the potentially state-changing call
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;

        bool reverted;
        // state-changing call must be a top-level statement
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterThis = address(this).balance;
        uint afterC = address(c).balance;

        // General invariant:
        // If call reverted: balances unchanged. If call succeeded: C.balance == 0 and this.balance >= beforeThis.
        assert(
            (reverted && afterThis == beforeThis && afterC == beforeC)
            || (!reverted && afterC == 0 && afterThis >= beforeThis)
        );
    }

    // allow receiving Ether if selfdestruct sends funds here
    receive() external payable {}
}

